      const wsH = hs.win_streak, wsA = as0.win_streak;
      const hotSide = wsH && wsH.result === "W" && wsH.n >= 3 ? "home" : wsA && wsA.result === "W" && wsA.n >= 3 ? "away" : null;
      const coldSide = wsH && wsH.result === "L" && wsH.n >= 3 ? "home" : wsA && wsA.result === "L" && wsA.n >= 3 ? "away" : null;
      const opts: string[] = [];
